<?php
// Handle POST first (before any output)
$error = '';
$debug = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    require_once dirname(__FILE__) . '/../../config/database.php';
        require_once dirname(__FILE__) . '/../../includes/auth.php';
            requireAuth();
                
                    $db = Database::getInstance();
                        
                            // Collect ALL form data
                                $national_id   = trim($_POST['national_id']   ?? '');
                                    $first_name    = trim($_POST['first_name']    ?? '');
                                        $family_name   = trim($_POST['family_name']   ?? '');
                                            $first_name_ar = trim($_POST['first_name_ar'] ?? '');
                                                $last_name_ar  = trim($_POST['last_name_ar']  ?? '');
                                                    $birth_date    = $_POST['birth_date']    ?? '';
                                                        $birth_place   = trim($_POST['birth_place']   ?? '');
                                                            $gender        = $_POST['gender']        ?? '';
                                                                $address       = trim($_POST['address']       ?? '');
                                                                    $neighborhood  = trim($_POST['neighborhood']  ?? '');
                                                                        $father_name   = trim($_POST['father_name']   ?? '');
                                                                            $mother_name   = trim($_POST['mother_name']   ?? '');
                                                                                $file_number   = trim($_POST['file_number']   ?? '');
                                                                                    $file_date     = trim($_POST['file_date']     ?? '');
                                                                                        $notes         = trim($_POST['notes']         ?? '');
                                                                                            
                                                                                                // Validate required fields
                                                                                                    if (empty($national_id) || empty($first_name) || empty($family_name) || empty($birth_date) || empty($gender)) {
                                                                                                            $error = 'Please fill in all required fields (National ID, First Name, Family Name, Birth Date, Gender).';
                                                                                                                } else {
                                                                                                                        // Check if national_id exists
                                                                                                                                $exists = $db->query("SELECT id FROM citizens WHERE national_id = ?", [$national_id])->fetch();
                                                                                                                                        
                                                                                                                                                if ($exists) {
                                                                                                                                                            $error = 'National ID already exists.';
                                                                                                                                                                    } else {
                                                                                                                                                                                // Handle photo upload
                                                                                                                                                                                            $photo_path = null;
                                                                                                                                                                                                        if (!empty($_FILES['photo']['name'])) {
                                                                                                                                                                                                                        $uploadDir = dirname(__FILE__) . '/../../uploads/photos/';
                                                                                                                                                                                                                                        if (!is_dir($uploadDir)) {
                                                                                                                                                                                                                                                            mkdir($uploadDir, 0755, true);
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                            $ext = strtolower(pathinfo($_FILES['photo']['name'], PATHINFO_EXTENSION));
                                                                                                                                                                                                                                                                                                            $allowed = ['jpg', 'jpeg', 'png', 'gif'];
                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                            if (in_array($ext, $allowed)) {
                                                                                                                                                                                                                                                                                                                                                                $filename = time() . '_' . bin2hex(random_bytes(4)) . '.' . $ext;
                                                                                                                                                                                                                                                                                                                                                                                    $photo_path = 'uploads/photos/' . $filename;
                                                                                                                                                                                                                                                                                                                                                                                                        $moved = move_uploaded_file($_FILES['photo']['tmp_name'], dirname(__FILE__) . '/../../' . $photo_path);
                                                                                                                                                                                                                                                                                                                                                                                                                            if (!$moved) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    $error = 'Failed to upload photo.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $error = 'Invalid photo format. Use JPG, PNG, or GIF.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Only insert if no error so far
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (empty($error)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $db->query(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "INSERT INTO citizens 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 (national_id, first_name, family_name, first_name_ar, last_name_ar, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           birth_date, birth_place, gender, address, neighborhood, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     father_name, mother_name, file_number, file_date, notes, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               photo_path, created_by) 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $national_id, $first_name, $family_name, $first_name_ar, $last_name_ar,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $birth_date, $birth_place, $gender, $address, $neighborhood,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $father_name, $mother_name, $file_number, $file_date, $notes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $photo_path, $_SESSION['user_id']
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    header('Location: index.php');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        exit;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (PDOException $e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $error = 'Database error: ' . $e->getMessage();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

